// Inequality in Cities — Comparison, route: jsx
// Source: inequality-in-american-cities
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from inequality ----
type CityRatio = { city: string; start: number; end: number };

/**
 * Synthetic stand-in for the NYT metro wage-inequality data: the ratio of 90th to
 * 10th percentile wages in 1980 and 2015. Every city name is invented, and every
 * figure is a fixed literal, so none of this describes a real place.
 */
const inequalityByCity: CityRatio[] = [
  { city: 'Aldermere', start: 3.42, end: 6.44 },
  { city: 'Thessport', start: 3.85, end: 6.71 },
  { city: 'Nyssford', start: 3.06, end: 5.79 },
  { city: 'Harrowmere', start: 4.12, end: 6.7 },
  { city: 'Calderfen', start: 3.58, end: 5.99 },
  { city: 'Vantry Cross', start: 3.24, end: 5.55 },
  { city: 'Orrinvale', start: 4.4, end: 6.62 },
  { city: 'Bexhollow', start: 3.77, end: 5.86 },
  { city: 'Emberlyn', start: 3.19, end: 5.17 },
  { city: 'Kelvinreach', start: 4.05, end: 5.93 },
  { city: 'Draymoor', start: 3.61, end: 5.4 },
  { city: 'Sablewick', start: 2.94, end: 4.63 },
  { city: 'Ivenport', start: 4.28, end: 5.87 },
  { city: 'Pellamy', start: 3.48, end: 4.99 },
  { city: 'Yarrowfield', start: 3.02, end: 4.44 },
  { city: 'Renforth', start: 3.9, end: 5.24 },
  { city: 'Gilroe Bay', start: 4.51, end: 5.77 },
  { city: 'Cindermoor', start: 3.35, end: 4.53 },
  { city: 'Umbervale', start: 2.88, end: 3.98 },
  { city: 'Fennwick', start: 3.72, end: 4.75 },
  { city: 'Quillhaven', start: 4.16, end: 5.12 },
  { city: 'Everlyn Falls', start: 3.29, end: 4.17 },
  { city: 'Bramblecourt', start: 3.95, end: 4.76 },
  { city: 'Lorrimer', start: 3.13, end: 3.87 },
  { city: 'Westermere', start: 4.62, end: 5.29 },
  { city: 'Ashgrove Point', start: 3.54, end: 4.13 },
  { city: 'Dellworth', start: 2.97, end: 3.49 },
  { city: 'Jessamy Ridge', start: 3.83, end: 4.27 },
  { city: 'Fairholt', start: 3.41, end: 3.72 },
  { city: 'Zephyr Bend', start: 4.09, end: 4.27 },
  { city: 'Mordant Hollow', start: 3.66, end: 3.61 },
  { city: 'Xanth Harbor', start: 4.33, end: 3.94 }
];

const MARGIN = { top: 44, right: 62, bottom: 56, left: 126 };
const START_COLOR = '#6ea8c7';
const END_COLOR = 'var(--accent)';

// Namespaced so they cannot collide with another chart's defs in the same document.
const ARROW_ID = 'inequality-arrow';
const LEGEND_GRADIENT_ID = 'inequality-legend-gradient';

// Below this row pitch the 11px axis text would overlap its neighbours.
const MIN_ROW_FOR_LABEL = 12;

const formatRatio = d3.format('.2f');
const formatTick = d3.format('~f');

/** One row per place, with its value at each end of the span. */
export type Data = { city: string; start: number; end: number }[];

export default function InequalityInCities({
  data = inequalityByCity,
  width
}: {
  data?: Data;
  width: number;
}) {
  const height = Math.round(width * 0.72);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  // Largest change on top, so the chart reads as a ranking of movement.
  const rows = useMemo(
    () => [...data].sort((a, b) => b.end - b.start - (a.end - a.start)),
    [data]
  );

  const x = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain(d3.extent(rows.flatMap((d) => [d.start, d.end])) as [number, number])
        .nice()
        .range([0, innerWidth]),
    [rows, innerWidth]
  );

  const y = useMemo(
    () =>
      d3
        .scaleBand<string>()
        .domain(rows.map((d) => d.city))
        .range([0, innerHeight]),
    [rows, innerHeight]
  );

  const xTicks: Tick[] = useMemo(
    () => x.ticks(6).map((v) => ({ value: formatTick(v), offset: x(v) })),
    [x]
  );

  const marks = useMemo(
    () =>
      rows.map((d) => ({
        ...d,
        slug: d.city.toLowerCase().replace(/[^a-z]/g, ''),
        x1: x(d.start),
        x2: x(d.end),
        cy: (y(d.city) ?? 0) + y.bandwidth() / 2,
        rising: d.end >= d.start
      })),
    [rows, x, y]
  );

  if (width === 0) return null;

  const showLabels = y.step() >= MIN_ROW_FOR_LABEL;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Dumbbell chart of the 90th-to-10th percentile wage ratio in 1980 and 2015 for thirty-two cities, one row each, sorted by the size of the change. The data is synthetic and the city names are invented; it is not a record of real US metro areas."
    >
      <defs>
        <marker id={ARROW_ID} markerWidth={10} markerHeight={10} refX={5} refY={2.5} orient="auto">
          <path fill={END_COLOR} d="M0,0v5l7,-2.5Z" />
        </marker>
        {marks.map((d) => (
          <linearGradient
            key={d.city}
            id={`inequality-${d.slug}`}
            gradientUnits="userSpaceOnUse"
            x1={d.x1}
            y1={d.cy}
            x2={d.x2}
            y2={d.cy}
          >
            <stop stopColor={START_COLOR} stopOpacity={0.5} />
            <stop offset="100%" stopColor={END_COLOR} />
          </linearGradient>
        ))}
        <linearGradient id={LEGEND_GRADIENT_ID} gradientUnits="userSpaceOnUse" x1={38} x2={92}>
          <stop stopColor={START_COLOR} stopOpacity={0.5} />
          <stop offset="100%" stopColor={END_COLOR} />
        </linearGradient>
      </defs>

      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <g className="axis">
          {xTicks.map((t) => (
            <line key={t.value} className="grid" x1={t.offset} x2={t.offset} y1={0} y2={innerHeight} />
          ))}
        </g>
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />

        <g fill="none" strokeWidth={1.5}>
          {marks.map((d) => (
            <line
              key={d.city}
              x1={d.x1}
              y1={d.cy}
              x2={d.x2}
              y2={d.cy}
              stroke={`url(#inequality-${d.slug})`}
              markerEnd={`url(#${ARROW_ID})`}
            >
              <title>{`${d.city}: ${formatRatio(d.start)} in 1980, ${formatRatio(d.end)} in 2015`}</title>
            </line>
          ))}
        </g>

        <g fill={START_COLOR}>
          {marks.map((d) => (
            <circle key={d.city} cx={d.x1} cy={d.cy} r={2.5} />
          ))}
        </g>

        {showLabels && (
          <g className="axis" textAnchor="end">
            {marks.map((d) => (
              <text key={d.city} x={-12} y={d.cy} dy="0.32em">
                {d.city}
              </text>
            ))}
          </g>
        )}

        {showLabels && (
          <g fill="var(--muted)" fontSize={10}>
            {marks.map((d) => (
              <text
                key={d.city}
                x={d.x2 + (d.rising ? 16 : -16)}
                y={d.cy}
                dy="0.32em"
                textAnchor={d.rising ? 'start' : 'end'}
              >
                {formatRatio(d.end)}
              </text>
            ))}
          </g>
        )}

        <g transform="translate(0,-26)" fontSize={11} fill="var(--muted)">
          <text dy="0.32em">1980</text>
          <line
            x1={38}
            x2={92}
            strokeWidth={1.5}
            stroke={`url(#${LEGEND_GRADIENT_ID})`}
            markerEnd={`url(#${ARROW_ID})`}
          />
          <circle cx={38} cy={0} r={2.5} fill={START_COLOR} />
          <text x={110} dy="0.32em">
            2015
          </text>
        </g>
        <text x={innerWidth} y={-26} dy="0.32em" textAnchor="end" fontSize={11} fill="var(--muted)">
          90th / 10th percentile wage ratio →
        </text>
      </g>

      <text x={MARGIN.left} y={height - 8} fontSize={10} fill="var(--muted)">
        Synthetic data from fixed literals, not real US metro wage statistics. The city names are invented.
      </text>
    </svg>
  );
}
